export type EmbedStatusType = "idle" | "checking" | "active";

export type OnboardingStateType = {
  currentStep: OnboardingStepIdType;
  direction: 1 | -1;
  storeName: string;
  storeCurrency: string;
  syncTasks: SyncTaskItemType[];
  syncComplete: boolean;
  coreTools: CoreToolType[];
