export type OnboardingActionType =
  | { type: "ADVANCE_SYNC_TASK" }
  | { type: "FORCE_SYNC_COMPLETE" }
  | { type: "GO_NEXT" }
  | { type: "GO_BACK" }
  | { type: "GO_TO_STEP"; step: OnboardingStepIdType }
  | { type: "SET_THRESHOLD"; amount: number }
  | { type: "SET_CURRENCY"; currency: string }
  | { type: "CONFIRM_THRESHOLD" }
  | { type: "TOGGLE_OPTIONAL_TOOL"; id: OptionalToolIdType }
  | { type: "SELECT_PRESET"; id: OptionalToolIdType; presetId: string }
  | { type: "CONFIRM_TOOL_CONFIG"; id: OptionalToolIdType }
  | { type: "DEFER_TOOL_CONFIG"; id: OptionalToolIdType }
  | { type: "SET_EMBED_STATUS"; status: EmbedStatusType }
  | { type: "COMPLETE_ONBOARDING" };

import React from "react";
import { Badge, Clickable, InlineStack } from "@xco-agency/corex-ui";
import type { OnboardingStepIdType, StepConfigItemType } from "./onboarding.types";

export type ProgressHeaderPropsType = {
  stepIndex: number;
  steps: StepConfigItemType[];
  onGoToStep?: (step: OnboardingStepIdType) => void;
};

export function ProgressHeader({
  stepIndex,
  steps,
  onGoToStep,
}: ProgressHeaderPropsType) {
  return (
    <InlineStack
      gap="small-300"
      justifyContent="center"
      alignItems="center"
      style={{ width: "100%", maxWidth: "640px" }}
    >
      {steps.map((item, idx) => {
        const isCompleted = idx < stepIndex;
        const isCurrent = idx === stepIndex;

        return (
          <React.Fragment key={item.id}>
            {idx > 0 && (
              <span
                style={{
                  flex: 1,
                  height: 2,
                  maxWidth: "2rem",
                  minWidth: "1rem",
                  backgroundColor: isCompleted ? "#059669" : "#e5e7eb",
                  borderRadius: "9999px",
                  transition: "background-color 250ms ease",
                }}
                aria-hidden="true"
              />
            )}
            {isCompleted ? (
              <Clickable
                onClick={() => onGoToStep?.(item.id)}
                accessibilityLabel={`Go back to ${item.label}`}
              >
                <Badge tone="success" size="large" icon="check">
                  {item.label}
                </Badge>
              </Clickable>
            ) : isCurrent ? (
              <Badge tone="info" size="large" icon={item.icon}>
                {item.label}
              </Badge>
            ) : (
              <Badge tone="auto" size="large" icon={item.icon}>
                {item.label}
              </Badge>
            )}
          </React.Fragment>
        );
      })}
    </InlineStack>
  );
}

import { useEffect, useRef, useState, type Dispatch } from "react";
import type { OnboardingActionType, OnboardingStateType } from "../onboarding.types";
import {
  Box,
  BlockStack,
  InlineStack,
  Button,
  Icon,
  IconTile,
  ProgressBar,
  Spinner,
  Text,
} from "@xco-agency/corex-ui";
import styles from "../onboarding.module.css";

const TASK_INTERVAL_MS = 750;
const HOLD_AFTER_COMPLETE_MS = 550;
const FALLBACK_VISIBLE_AFTER_MS = 6500;

export type Step1InitializingPropsType = {
  state: OnboardingStateType;
  dispatch: Dispatch<OnboardingActionType>;
};

export function Step1Initializing({ state, dispatch }: Step1InitializingPropsType) {
  const [showFallback, setShowFallback] = useState(false);
  const wasAlreadyComplete = useRef(state.syncComplete);
  const hasAutoAdvanced = useRef(false);

  // Safety net: never trap a merchant behind a spinner indefinitely.
  useEffect(() => {
    const timer = window.setTimeout(
      () => setShowFallback(true),
      FALLBACK_VISIBLE_AFTER_MS,
    );
    return () => window.clearTimeout(timer);
  }, []);

  // Advance one checklist item at a time, at a pace that feels real but never drags.
  useEffect(() => {
    if (state.syncComplete) return;
    const timer = window.setTimeout(
      () => dispatch({ type: "ADVANCE_SYNC_TASK" }),
      TASK_INTERVAL_MS,
    );
    return () => window.clearTimeout(timer);
  }, [state.syncTasks, state.syncComplete, dispatch]);

  // On initial sync completion (first run), advance automatically after a beat.
  useEffect(() => {
    if (!state.syncComplete || wasAlreadyComplete.current || hasAutoAdvanced.current)
      return;
    hasAutoAdvanced.current = true;
    const timer = window.setTimeout(
      () => dispatch({ type: "GO_NEXT" }),
      HOLD_AFTER_COMPLETE_MS,
    );
    return () => window.clearTimeout(timer);
  }, [state.syncComplete, dispatch]);

  const doneCount = state.syncTasks.filter((task) => task.status === "done").length;
  const firstPendingIndex = state.syncTasks.findIndex((task) => task.status !== "done");

  return (
    <Box paddingBlock="small">
      <BlockStack gap="large" alignItems="center">
        <Box
          padding="large-400"
          border="base"
          borderRadius="large"
          background="base"
          inlineSize="100%"
          maxInlineSize="440px"
        >
          <BlockStack gap="base" alignItems="center">
            {state.syncComplete ? (
              <IconTile tone="success" size="large">
                <Icon type="check" tone="success" />
              </IconTile>
            ) : (
              <Spinner accessibilityLabel="Syncing store" size="large" />
            )}

            <Text
              heading
              tooltip="We are automatically syncing your product catalog, multi-currency settings, and initializing your store's revenue engine."
            >
              {state.syncComplete ? "Store setup complete" : "Setting up Journeva"}
            </Text>

            <Text color="subdued">
              {state.syncComplete
                ? "Your store data and revenue engine have been synchronized successfully."
                : "Sit tight — we’re syncing your store and provisioning your revenue engine."}
            </Text>

            <Box paddingBlock="small-100" inlineSize="100%">
              <BlockStack gap="small-200">
                {state.syncTasks.map((task, i) => {
                  const isDone = task.status === "done";
                  const isActive = !isDone && i === firstPendingIndex;

                  return (
                    <div
                      key={task.id}
                      className={styles.staggerItem}
                      style={{ animationDelay: `${i * 160}ms` }}
                    >
                      <InlineStack gap="small-200" alignItems="center">
                        {isDone ? (
                          <Icon type="check-circle-filled" tone="success" />
                        ) : isActive ? (
                          <Spinner accessibilityLabel="Syncing task" size="small" />
                        ) : (
                          <Icon type="clock" tone="neutral" />
                        )}
                        {isActive || isDone ? (
                          <Text heading>{task.label}</Text>
                        ) : (
                          <Text color="subdued">{task.label}</Text>
                        )}
                      </InlineStack>
                    </div>
                  );
                })}
              </BlockStack>
            </Box>

            <ProgressBar
              progress={(doneCount / state.syncTasks.length) * 100}
              tone="success"
              style={{ marginTop: "1rem" }}
            />
          </BlockStack>
        </Box>

        {state.syncComplete ? (
          <Button variant="primary" onClick={() => dispatch({ type: "GO_NEXT" })}>
            Continue
          </Button>
        ) : showFallback ? (
          <Button
            variant="tertiary"
            onClick={() => dispatch({ type: "FORCE_SYNC_COMPLETE" })}
          >
            Taking longer than usual? Continue anyway
          </Button>
        ) : null}
      </BlockStack>
    </Box>
  );
}

import type { Dispatch } from "react";
import type { OnboardingActionType, OnboardingStateType } from "../onboarding.types";
import { CURRENCIES, SAMPLE_CART_TOTAL } from "../constants";
import {
  Box,
  BlockStack,
  InlineStack,
  Button,
  Icon,
  IconTile,
  ProgressBar,
  Select,
  Text,
  TextField,
  NumberField,
} from "@xco-agency/corex-ui";

function formatCurrency(amount: number, currency: string): string {
  try {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
      maximumFractionDigits: 0,
    }).format(amount);
  } catch {
    return `${currency} ${amount}`;
  }
}

export type Step3ConfigurationPropsType = {
  state: OnboardingStateType;
  dispatch: Dispatch<OnboardingActionType>;
};

export function Step3Configuration({ state, dispatch }: Step3ConfigurationPropsType) {
  const threshold = state.freeShippingThreshold;
  const remaining = Math.max(0, threshold - SAMPLE_CART_TOTAL);
  const qualifies = SAMPLE_CART_TOTAL >= threshold && threshold > 0;
  const percent =
    threshold > 0 ? Math.min(100, (SAMPLE_CART_TOTAL / threshold) * 100) : 100;

  const handleAmountChange = (value: string) => {
    const parsed = Number(value.replace(/[^0-9.]/g, ""));
    dispatch({
      type: "SET_THRESHOLD",
      amount: Number.isFinite(parsed) ? Math.max(0, parsed) : 0,
    });
  };

  return (
    <Box paddingBlock="large">
      <BlockStack gap="large" alignItems="center" style={{ width: "100%" }}>
        <BlockStack gap="small-300" alignItems="center">
          <IconTile tone="caution">
            <Icon type="delivery" tone="caution" />
          </IconTile>
          <Text
            heading
            variant="large"
            tooltip="Customers will see a dynamic progress bar in the Cart Drawer encouraging them to add more items to earn free shipping."
          >
            One quick detail
          </Text>
          <Text color="subdued">
            Set your free shipping threshold — we&rsquo;ll handle the rest.
          </Text>
        </BlockStack>
        <Box
          padding="large-200"
          border="base"
          borderRadius="large"
          inlineSize="100%"
          background="base"
        >
          <BlockStack gap="large-100" alignItems="center" style={{ width: "100%" }}>
            <Box inlineSize="100%">
              <InlineStack gap="small-200" alignItems="start">
                <Box inlineSize="120px">
                  <Select
                    label="Currency"
                    value={state.storeCurrency}
                    options={CURRENCIES}
                    onChange={(currency) =>
                      dispatch({
                        type: "SET_CURRENCY",
                        currency,
                      })
                    }
                  />
                </Box>
                <Box inlineSize="100%">
                  <NumberField
                    label="Free shipping threshold"
                    value={String(threshold)}
                    onChange={handleAmountChange}
                    autoComplete="off"
                  />
                </Box>
              </InlineStack>
            </Box>

            <Box
              padding="base"
              border="base"
              borderRadius="base"
              background="subdued"
              inlineSize="100%"
            >
              <BlockStack gap="small-100">
                <InlineStack justifyContent="space-between" alignItems="center">
                  <Text color="subdued">SAMPLE CART TOTAL</Text>
                  <Text heading>
                    {formatCurrency(SAMPLE_CART_TOTAL, state.storeCurrency)}
                  </Text>
                </InlineStack>

                <ProgressBar progress={percent} size="base" tone="neutral" />

                <Text tone="success" heading>
                  {qualifies
                    ? "This cart qualifies for free shipping."
                    : `Add ${formatCurrency(remaining, state.storeCurrency)} more for free shipping.`}
                </Text>
              </BlockStack>
            </Box>
          </BlockStack>
        </Box>
        <BlockStack gap="small-200" style={{ width: "100%" }} alignItems="center">
          <InlineStack
            gap="small-200"
            style={{ width: "100%" }}
            justifyContent="space-between"
          >
            <Button onClick={() => dispatch({ type: "GO_BACK" })}>Back</Button>
            <Button
              variant="primary"
              onClick={() => {
                dispatch({ type: "CONFIRM_THRESHOLD" });
                dispatch({ type: "GO_NEXT" });
              }}
            >
              Save &amp; continue
            </Button>
          </InlineStack>
          <Button variant="tertiary" onClick={() => dispatch({ type: "GO_NEXT" })}>
            Skip for now — I&rsquo;ll set this later
          </Button>
        </BlockStack>
      </BlockStack>
    </Box>
  );
}

